#include "ec.hpp"
struct Count{U addsub=0,multiply=0,inverse=0;json wire()const{return {{"field_add_sub",addsub},{"field_multiply_including_inverse_power",multiply},{"field_inverse",inverse}};}};
U cmul(U a,U b,Count&c){c.multiply++;return mul(a,b);}U cadd(U a,U b,Count&c){c.addsub++;return add(a,b);}U csub(U a,U b,Count&c){c.addsub++;return sub(a,b);}U cinv(U a,Count&c){need(a,"map inverse zero");c.inverse++;U r=1,n=PRIME-2;for(;n;n>>=1,a=cmul(a,a,c))if(n&1)r=cmul(r,a,c);return r;}
struct Kernel{U r,v,u;};
Point measured(Point P,const Kernel&e,Count&c){if(P.infinity)return{};U r=e.r,v=e.v,u=e.u,d=csub(P.x,r,c);if(!d)return{};U di=cinv(d,c),x=cadd(P.x,cmul(v,di,c),c),y=cmul(P.y,csub(1,cmul(v,cmul(di,di,c),c),c),c),u2=cmul(u,u,c);return{cmul(u2,x,c),cmul(cmul(u2,u,c),y,c),false};}
int main(int argc,char**argv){try{need(argc==2,"ROOT");std::string root=argv[1];need(!std::filesystem::exists(root+"/data/map_measurements.jsonl"),"refuse overwrite");auto f=load(root+"/data/family.json"),fixtures=load(root+"/data/fixtures.json");std::ofstream log(root+"/data/map_measurements.jsonl");U count=0;for(const auto&e:f["edges"]){int a=e["source"];Kernel kernel{val(e["kernel_x"]),val(e["v"]),val(e["u"])};for(const auto&row:fixtures[std::to_string(a)]){Point P=point(row["P"]),Q=point(row["Q"]),expectedP=map_point(P,e),expectedQ=map_point(Q,e);for(int repeat=0;repeat<5;repeat++){Count c;U start=ns();Point mp=measured(P,kernel,c),mq=measured(Q,kernel,c);U elapsed=ns()-start;need(mp==expectedP&&mq==expectedQ,"instrumented map mismatch");log<<json({{"edge",e["id"]},{"source",a},{"target",e["target"]},{"instance",row["id"]},{"repeat",repeat},{"pair_wall_ns",elapsed},{"counters",c.wire()},{"P_image",wire(mp)},{"Q_image",wire(mq)},{"point_order_before",std::to_string(ORDER)},{"point_order_after",std::to_string(ORDER)},{"order_evidence","native_validation.json verifies exact source and image prime orders outside this timing"},{"instrumented_reference_map",true},{"verified",true}}).dump()<<'\n';count++;}}}log.close();save(root+"/data/map_measurement_validation.json",{{"passed",true},{"records",count},{"directed_maps",90},{"instances_per_map",100},{"repetitions",5},{"point_pair_images_match_uninstrumented_reference",true},{"local_timing_class","L0 concurrent work; no fastest-map claim"}});std::cout<<count<<" map-pair timings and complete reference arithmetic counts verified\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
